const inp = ($input.first()?.json || {});
const src = inp.output || inp;
let b1 = String(src.bubble1 ?? '').trim();
let b2 = String(src.bubble2 ?? '').trim();
let b3 = String(src.bubble3 ?? '').trim();
let draft = '';
try { draft = String($('Receptionist Agent').first()?.json?.output || ''); } catch (e) {}
function clean(s) {
  s = String(s || '');
  s = s.replace(/\*\*(.+?)\*\*/g, '$1').replace(/__(.+?)__/g, '$1').replace(/`([^`]+)`/g, '$1');
  s = s.replace(/^#{1,6}\s+/gm, '').replace(/^\s*[-*] +/gm, '');
  s = s.replace(/[ \t]+/g, ' ').trim();
  return s;
}
function stripProfile(s) {
  return String(s || '').replace(/^.*PROFILE:.*$/gmi, '').replace(/[ \t]+/g, ' ').trim();
}
try {
  b1 = clean(b1); b2 = clean(b2); b3 = clean(b3);
  const emo = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\uFE0F]/gu;
  b1 = b1.replace(emo, ''); b2 = b2.replace(emo, ''); b3 = b3.replace(emo, '');
  b1 = stripProfile(b1); b2 = stripProfile(b2); b3 = stripProfile(b3);
  const REFUSAL = 'Maaf, saya tidak bisa membantu.';
  if ([b1, b2, b3, draft].some(function (t) { return String(t).includes(REFUSAL); })) {
    return [{ json: { output: { bubble1: REFUSAL, bubble2: '', bubble3: '' } } }];
  }
  if (!b1) {
    b1 = stripProfile(clean(String(draft).trim().split('\n')[0].slice(0, 300))) || 'Mohon maaf kak, mohon ditunggu sebentar.';
  }
  b1 = b1.replace(/[!?]+/g, '.').replace(/\.\.+/g, '.');
  b2 = b2.replace(/[!?]+/g, '.').replace(/\.\.+/g, '.');
  function fixText(s) {
    s = s.replace(/(\d{1,2} [A-Za-z]+ \d{4})\s*(waktu\s+WITA|WITA)/g, '$1');
    s = s.replace(/ketersediaannya/gi, 'kamar yang tersedia').replace(/ketersediaan/gi, 'kamar yang tersedia').replace(/menginformasikan/gi, 'kasih tahu');
    s = s.replace(/\s+[Yy]a(?=[,.!?:]|$)/g, '');
    return s.trim();
  }
  b1 = fixText(b1); b2 = fixText(b2); b3 = fixText(b3);
  if (/check-?in|check-?out/i.test(b1 + b2 + b3)) {
    const addWita = function (s) { return s.replace(/(\b(?:1[0-9]|2[0-3]|[0-9]):[0-5]\d\b)(?!\s*WITA)/g, '$1 WITA'); };
    b1 = addWita(b1); b2 = addWita(b2); b3 = addWita(b3);
  }
  if (/putu/i.test(b1)) {
    b2 = b2.replace(/[^.]*putu[^.]*\.?/gi, '').replace(/[ \t]+/g, ' ').trim();
    b3 = b3.replace(/[^.]*perkenalkan[^.]*\.?/gi, '').replace(/[ \t]+/g, ' ').trim();
  }
  const claimsSuccess = /reservasi berhasil/i.test(b1 + ' ' + b2 + ' ' + b3);
  const draftHasId = /(reservasi berhasil|ID Reservasi|reservation)/i.test(draft);
  if (claimsSuccess && !draftHasId) {
    return [{ json: { output: { bubble1: 'Mohon maaf kak, mohon ditunggu sebentar.', bubble2: '', bubble3: 'Boleh saya bantu cek kembali kak?' } } }];
  }
  if (b1 && !/[.!?]$/.test(b1)) b1 += '.';
  if (b2 && !/[.!?]$/.test(b2)) b2 += '.';
  if (b3) {
    const qs = (b3.match(/\?/g) || []).length;
    if (qs > 1) { b3 = b3.split('?')[0].trim() + '?'; }
    if (!/[.?]$/.test(b3)) b3 += '.';
  }
  if (b1.length > 400) b1 = b1.slice(0, 400).trim() + '.';
  if (b2.length > 400) b2 = b2.slice(0, 400).trim() + '.';
  if (b3.length > 200) b3 = b3.slice(0, 200).trim();
  return [{ json: { output: { bubble1: b1, bubble2: b2, bubble3: b3 } } }];
} catch (e) {
  const fb = (b1 || 'Mohon maaf kak, mohon ditunggu sebentar.').slice(0, 400);
  return [{ json: { output: { bubble1: fb, bubble2: '', bubble3: '' } } }];
}

const loaded = (() => { try { return $('Load Guest Profile').first().json || {}; } catch (e) { return {}; } })();
let draft = '';
try { draft = String($('Receptionist Agent').first().json.output || ''); } catch (e) {}
let sid = '';
try { sid = String($('SOP').item.json.sessionId || ''); } catch (e) {}
if (!sid) { try { sid = String($('Chat Trigger').item.json.sessionId || ''); } catch (e) {} }
if (!sid) {
  try {
    const u = $('Telegram Trigger').first().json || {};
    const m = u.message || u.edited_message || u.channel_post || {};
    const cid = m?.chat?.id;
    if (cid !== undefined && cid !== '') sid = 'tg-' + String(cid);
  } catch (e) {}
}
const fields = ['name', 'phone', 'email', 'from_date', 'to_date', 'room_type', 'quantity', 'reservation_ids'];
const out = { session_id: sid };
for (const f of fields) {
  const v = loaded[f];
  out[f] = (v === undefined || v === null) ? '' : String(v);
}
const m = draft.match(/^.*PROFILE:(.*)$/mi);
if (m) {
  const parts = m[1].split('|');
  const map = { name: 'name', phone: 'phone', email: 'email', type: 'room_type', qty: 'quantity', reservations: 'reservation_ids' };
  let datesVal = '';
  for (const p of parts) {
    const eq = p.indexOf('=');
    if (eq < 0) continue;
    const k = p.slice(0, eq).trim().toLowerCase();
    const v = p.slice(eq + 1).trim();
    if (!v || v.toLowerCase() === 'none') continue;
    if (k === 'dates') { datesVal = v; continue; }
    if (map[k]) out[map[k]] = v;
  }
  const dm = datesVal.match(/([0-9]{4}-[0-9]{2}-[0-9]{2}) +to +([0-9]{4}-[0-9]{2}-[0-9]{2})/);
  if (dm) { out.from_date = dm[1]; out.to_date = dm[2]; }
}
return [{ json: out }];

